"""Per-unit output within the day (notes 21.98): running capacity by hour, start-ups, and the evening after a midday trough."""
import glob, numpy as np, pandas as pd, warnings; warnings.filterwarnings("ignore")
SP = "/tmp/claude-0/-home-user-EpexPredictor/d6125cc0-c431-5b93-a06f-0110cd871ab6/scratchpad"; RES = {}
for fuel in ("lignite", "coal", "gas"):
    P = []
    for area in ("DE_50HZ", "DE_AMPRION", "DE_TENNET", "DE_TRANSNET"):
        fs = sorted(glob.glob(f"{SP}/entsoe/units_all/{area}_{fuel}_*.parquet"))
        if not fs: continue
        x = pd.concat([pd.read_parquet(f) for f in fs]).sort_index(); x = x[~x.index.duplicated()]; x.columns = [f"{area[3:]}:{c.split(' | ')[0]}" for c in x.columns]; P.append(x.T.groupby(level=0).sum(min_count=1).T)
    U = pd.concat(P, axis=1) / 1000; U.index = U.index.tz_convert("Europe/Berlin"); cap = U.quantile(0.995); live = [u for u in U.columns if cap[u] > 0.05]; U = U[live]; cap = cap[live]; on = (U > 0.10 * cap) & U.notna(); day = U.index.normalize(); full = U.groupby(day).size(); good = full[full == 24].index; m = np.isin(day, good); U, on = U[m], on[m]; day = U.index.normalize(); hod = U.index.hour
    run_cap = (on * cap).sum(1); out = U.sum(1); n_on = on.sum(1); st = (on & ~on.shift(1, fill_value=False)); st[hod == 0] = False; sd_ = (~on & on.shift(1, fill_value=False)); sd_[hod == 0] = False
    T = pd.DataFrame(dict(run_cap=run_cap, out=out, n_on=n_on, starts=(st * cap).sum(1), stops=(sd_ * cap).sum(1), nstarts=st.sum(1)), index=U.index); T["day"] = day; T["hod"] = hod; RES[fuel] = (T, cap, len(live))
    su = T.index.month.isin(range(4, 10)); print(f"{fuel}: {len(live)} units, capacity {cap.sum():.1f} GW, {len(good)} full days | running capacity GW by hour (April-September / October-March): " + ", ".join(f"{h:02d}h {T.run_cap[su & (T.hod == h)].mean():.1f}/{T.run_cap[~su & (T.hod == h)].mean():.1f}" for h in (3, 7, 12, 15, 19, 22)))
    print(f"   start-ups GW per day by hour block (summer / winter): 04-08h {T.starts[su & T.hod.between(4, 7)].sum() / T.day[su].nunique():.2f}/{T.starts[~su & T.hod.between(4, 7)].sum() / T.day[~su].nunique():.2f}, 08-14h {T.starts[su & T.hod.between(8, 13)].sum() / T.day[su].nunique():.2f}/{T.starts[~su & T.hod.between(8, 13)].sum() / T.day[~su].nunique():.2f}, 14-20h {T.starts[su & T.hod.between(14, 19)].sum() / T.day[su].nunique():.2f}/{T.starts[~su & T.hod.between(14, 19)].sum() / T.day[~su].nunique():.2f}, other {T.starts[su & ~T.hod.between(4, 19)].sum() / T.day[su].nunique():.2f}/{T.starts[~su & ~T.hod.between(4, 19)].sum() / T.day[~su].nunique():.2f} | loading of running units (output / running capacity) at 12h and 19h, summer: {(T.out / T.run_cap)[su & (T.hod == 12)].mean():.2f} / {(T.out / T.run_cap)[su & (T.hod == 19)].mean():.2f}")
