pd.concat([T.assign(fuel=f)[["run_cap", "out", "starts", "hod", "day", "fuel"]] for f, (T, c, n) in RES.items()]).to_parquet(f"{SP}/out/unit_hours.parquet")
G = pd.read_csv(f"{SP}/out/eve_days.csv", index_col=0); G.index = pd.to_datetime(G.index, utc=True).tz_convert("Europe/Berlin").normalize(); rows = []
for fuel, (T, cap, nl) in RES.items():
    md = T[T.hod.between(10, 15)].groupby("day").agg(rc_md=("run_cap", "mean"), out_md=("out", "mean")); ev = T[T.hod.between(17, 20)].groupby("day").agg(rc_ev=("run_cap", "mean"), out_ev=("out", "mean")); mx = T.groupby("day").run_cap.max().rename("rc_max"); stv = T[T.hod.between(14, 20)].groupby("day").starts.sum().rename("st_ev"); J = md.join(ev).join(mx).join(stv).add_suffix(f"_{fuel}"); rows.append(J)
J = pd.concat(rows, axis=1).join(G[["D_ev", "D_md", "trough", "p_ev", "r_ev", "th_ev", "th_md", "shT_ev", "month", "tr"]], how="inner").dropna(); J.to_csv(f"{SP}/out/unit_days.csv"); print("days with unit data and the evening table:", len(J), "| share of total thermal output covered by the units, evening:", round(float(((J.out_ev_lignite + J.out_ev_coal + J.out_ev_gas) / J.th_ev).mean()), 2))
def ols(y, X, names):
    X = np.column_stack([X, np.ones(len(y))]); b = np.linalg.lstsq(X, y, rcond=None)[0]; r = y - X @ b; n, k = X.shape; cov = np.linalg.inv(X.T @ X) @ (X.T * r ** 2) @ X @ np.linalg.inv(X.T @ X) * n / (n - k); return "  ".join(f"{a} {c:+.3f} ±{s:.3f}" for a, c, s in zip(names, b, np.sqrt(np.diag(cov)))) + f" | R2 {1 - r.var() / y.var():.2f}"
