    print(f"{fuel}: evening running capacity on midday running capacity, evening demand:", ols(J[f"rc_ev_{fuel}"].values, J[[f"rc_md_{fuel}", "D_ev"]].values, ["midday running", "D_ev"])); print(f"   evening OUTPUT on evening running capacity, evening price/cost:", ols(J[f"out_ev_{fuel}"].values, J[[f"rc_ev_{fuel}", "r_ev"]].values, ["running", "price/cost"]))
